def mean(values: list[float]) -> float:
    if not values:
        return 0.0
    return sum(values) / len(values)

def parse_port(text: str) -> int:
    port = int(text)
    if not 1 <= port <= 65535:
        raise ValueError('port out of range')
    return port

async def count_after(awaitable) -> int:
    items = await awaitable
    return len(items)

def positive(values):
    for value in values:
        if value > 0:
            yield value

template<typename T>
T clamp_value(T value, T lower, T upper) {
    if (value < lower) return lower;
    if (upper < value) return upper;
    return value;
}
